  template <class T1> Text engine_audio_rolloff_name(const T1& r) const { return from_value<Text>(this->kern_engine("engine.audio.rolloff_name", {to_value(r)}, {PinType::text})[0].converted(pin_type_of<Text>())); }
  template <class T1> void engine_audio_parse_rolloff(const Text& s, const T1& out) { this->kern_engine("engine.audio.parse_rolloff", {to_value(s), to_value(out)}, {PinType::boolean, PinType::enumeration}); }
  template <class KernNode, class T1> void engine_audio_parse_rolloff(KernNode& kern_n, const Text& s, const T1& out) { const std::vector<Value> kern_out = this->kern_engine("engine.audio.parse_rolloff", {to_value(s), to_value(out)}, {PinType::boolean, PinType::enumeration}); kern_n.result = from_value<std::remove_cvref_t<decltype(kern_n.result)>>(kern_out[0]); kern_n.out = from_value<std::remove_cvref_t<decltype(kern_n.out)>>(kern_out[1]); }
