  template <class KernNode> void engine_mixer_adopt_clip(KernNode& kern_n, Int mixer, const List<Float>& samples, Int channels, const Text& name, Bool loopable) { const std::vector<Value> kern_out = this->kern_engine("engine.mixer.adopt_clip", {to_value(mixer), to_value(samples), to_value(channels), to_value(name), to_value(loopable)}, {PinType::integer}); kern_n.result = from_value<std::remove_cvref_t<decltype(kern_n.result)>>(kern_out[0]); }
